package cars;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.nio.file.Path;
import java.util.List;
/** Графічний застосунок, що об'єднує лабораторні роботи 8–11. */
public class Main extends JFrame {
    private final CarManager manager=new CarManager();
    private CarDatabase database;
    private final JTable arrays=table(false), strings=table(false), files=table(false), db=table(true);
    private Car[] arrayView=manager.all();
    private interface Task { void run() throws Exception; }
    /** Створює головне вікно та вкладки лабораторних робіт. */
    public Main(){super("Java — модуль 2 | Автомобілі");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1050,620);setLocationRelativeTo(null);JTabbedPane tabs=new JTabbedPane();tabs.addTab("ЛР 8 — Масиви",arrayPanel());tabs.addTab("ЛР 9 — Рядки",stringPanel());tabs.addTab("ЛР 10 — Файли",filePanel());tabs.addTab("ЛР 11 — SQLite",dbPanel());add(tabs);refreshArrays(manager.all());refresh(strings,manager.all());refresh(files,manager.all());try{database=new CarDatabase("cars.db");refreshDb(null);}catch(Exception e){error(e);}}
    private static JTable table(boolean database){JTable t=new JTable(new DefaultTableModel(database?new String[]{"ID","Марка","Модель","Рік","Ціна"}:new String[]{"Марка","Модель","Рік","Ціна","Двигун, л"},0){public boolean isCellEditable(int r,int c){return false;}});t.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);t.setRowHeight(26);t.getTableHeader().setReorderingAllowed(false);return t;}
    private JPanel panel(JTable t,JPanel controls,String hint){JPanel p=new JPanel(new BorderLayout(8,8));p.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));p.add(controls,BorderLayout.NORTH);p.add(new JScrollPane(t),BorderLayout.CENTER);p.add(new JLabel(hint),BorderLayout.SOUTH);return p;}
    private JPanel controls(){return new JPanel(new GridLayout(0,3,6,6));}
    private void button(JPanel p,String label,Task task){JButton b=new JButton(label);p.add(b);b.addActionListener(e->{try{task.run();}catch(Exception ex){error(ex);}});}
    private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Помилка",JOptionPane.ERROR_MESSAGE);}
    private String ask(String prompt,String initial){return JOptionPane.showInputDialog(this,prompt,initial);}
    private Double threshold(){String s=ask("Введіть мінімальну ціну:","20000");if(s==null)return null;double v=Double.parseDouble(s.trim());if(!Double.isFinite(v)||v<0)throw new IllegalArgumentException("Некоректна ціна");return v;}
    private Car editDialog(Car old,boolean engine){JTextField brand=new JTextField(old==null?"":old.getBrand()),model=new JTextField(old==null?"":old.getModel()),year=new JTextField(old==null?"2020":""+old.getYear()),price=new JTextField(old==null?"20000":""+old.getPrice()),volume=new JTextField(old==null?"2.0":""+old.getEngine().volume());JPanel p=new JPanel(new GridLayout(0,2,5,5));p.add(new JLabel("Марка"));p.add(brand);p.add(new JLabel("Модель"));p.add(model);p.add(new JLabel("Рік"));p.add(year);p.add(new JLabel("Ціна"));p.add(price);if(engine){p.add(new JLabel("Об'єм двигуна"));p.add(volume);}if(JOptionPane.showConfirmDialog(this,p,"Дані автомобіля",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return null;return new Car(brand.getText().trim(),model.getText().trim(),Integer.parseInt(year.getText().trim()),Double.parseDouble(price.getText().trim()),engine?Double.parseDouble(volume.getText().trim()):0);}
    private void refresh(JTable table,Car[] data){DefaultTableModel m=(DefaultTableModel)table.getModel();m.setRowCount(0);for(Car c:data)m.addRow(new Object[]{c.getBrand(),c.getModel(),c.getYear(),c.getPrice(),c.getEngine().volume()});}
    private void refreshArrays(Car[] data){arrayView=data;refresh(arrays,data);}
    private void changed(){refreshArrays(manager.all());refresh(strings,manager.all());refresh(files,manager.all());}
    private JPanel arrayPanel(){JPanel p=controls();button(p,"Усі автомобілі",()->refreshArrays(manager.all()));button(p,"Ціна ↑",()->refreshArrays(manager.sortPrice(false)));button(p,"Ціна ↓",()->refreshArrays(manager.sortPrice(true)));button(p,"Фільтр за ціною",()->{Double v=threshold();if(v!=null)refreshArrays(manager.filterPrice(v));});button(p,"Мінімум / максимум",()->refreshArrays(manager.minMax()));button(p,"Додати",()->{Car c=editDialog(null,true);if(c!=null){manager.add(c);changed();}});button(p,"Редагувати",()->{int r=arrays.getSelectedRow();if(r<0)throw new IllegalArgumentException("Виберіть рядок");Car old=arrayView[r];Car c=editDialog(old,true);if(c!=null){Car[] all=manager.all();for(int i=0;i<all.length;i++)if(all[i]==old){manager.edit(i,c);break;}changed();}});return panel(arrays,p,"ЛР 8: масив об'єктів, Comparator, редагування та фільтрація.");}
    private JPanel stringPanel(){JPanel p=controls();button(p,"Усі автомобілі",()->refresh(strings,manager.all()));button(p,"Марка А–Я",()->refresh(strings,manager.sortBrand(false)));button(p,"Марка Я–А",()->refresh(strings,manager.sortBrand(true)));button(p,"Пошук Regex",()->{String s=ask("Регулярний вираз (марка та модель)","^T");if(s!=null)refresh(strings,manager.filterRegex(s));});button(p,"Мінімум / максимум ціни",()->refresh(strings,manager.minMax()));return panel(strings,p,"ЛР 9: сортування рядків та регулярні вирази. Приклад: ^T або Corolla|Civic.");}
    private Path choose(boolean save,String initial){JFileChooser fc=new JFileChooser(".");fc.setSelectedFile(new java.io.File(initial));int result=save?fc.showSaveDialog(this):fc.showOpenDialog(this);return result==JFileChooser.APPROVE_OPTION?fc.getSelectedFile().toPath():null;}
    private JPanel filePanel(){JPanel p=controls();button(p,"Завантажити TXT",()->{Path f=choose(false,"cars.txt");if(f!=null){manager.loadFromText(f);changed();}});button(p,"Записати відсортований DAT",()->{Path f=choose(true,"cars.dat");if(f!=null){if(java.nio.file.Files.exists(f)&&JOptionPane.showConfirmDialog(this,"Перезаписати файл?","Підтвердження",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;manager.saveSortedToBinary(f);refresh(files,manager.sortPrice(false));JOptionPane.showMessageDialog(this,"Файл збережено");}});button(p,"Прочитати DAT",()->{Path f=choose(false,"cars.dat");if(f!=null)refresh(files,manager.showFromBinary(f));});return panel(files,p,"ЛР 10: TXT → масив → сортування за ціною → DAT → читання.");}
    private CarDatabase database() throws Exception{if(database==null)database=new CarDatabase("cars.db");return database;}
    private void refreshDb(Double min)throws Exception{List<CarDatabase.Row> rows=database().select(min);DefaultTableModel m=(DefaultTableModel)db.getModel();m.setRowCount(0);for(CarDatabase.Row row:rows){Car c=row.car();m.addRow(new Object[]{row.id(),c.getBrand(),c.getModel(),c.getYear(),c.getPrice()});}}
    private int selectedDb(){int r=db.getSelectedRow();if(r<0)throw new IllegalArgumentException("Виберіть рядок у таблиці");return r;}
    private JPanel dbPanel(){JPanel p=controls();button(p,"Показати всі (SELECT)",()->refreshDb(null));button(p,"Додати (INSERT)",()->{Car c=editDialog(null,false);if(c!=null){database().insert(c);refreshDb(null);}});button(p,"Фільтр (WHERE)",()->{Double v=threshold();if(v!=null)refreshDb(v);});button(p,"Редагувати (UPDATE)",()->{int r=selectedDb();int id=(Integer)db.getValueAt(r,0);Car old=new Car((String)db.getValueAt(r,1),(String)db.getValueAt(r,2),(Integer)db.getValueAt(r,3),(Double)db.getValueAt(r,4),0);Car c=editDialog(old,false);if(c!=null){database().update(id,c);refreshDb(null);}});button(p,"Видалити (DELETE)",()->{int r=selectedDb();if(JOptionPane.showConfirmDialog(this,"Видалити автомобіль?","Підтвердження",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION){database().delete((Integer)db.getValueAt(r,0));refreshDb(null);}});button(p,"Додати тестові дані",()->{if(!database().select(null).isEmpty()){JOptionPane.showMessageDialog(this,"Таблиця вже містить дані");return;}for(Car c:CarManager.samples())database().insert(c);refreshDb(null);});return panel(db,p,"ЛР 11: окрема база cars.db, JDBC та параметризовані SQL-запити.");}
    /** Точка входу програми.
     * @param args аргументи командного рядка
     */
    public static void main(String[] args){SwingUtilities.invokeLater(()->new Main().setVisible(true));}
}
